/**
 * Semantic layer: one definition per metric (docs/13 §3–4). Dashboards, the Insight Hand, benchmarks
 * and packs all render from these definitions; no surface computes a metric its own way.
 */
export type MetricGroup = 'access' | 'operations' | 'clinical_quality' | 'patient_experience' | 'referrer' | 'revenue_cycle' | 'finance' | 'workforce' | 'assets' | 'compliance' | 'ai_ops' | 'shareholder';
export type Direction = 'higher' | 'lower' | 'band';
export type Freshness = 'live' | 'near_live' | 'daily' | 'monthly';
export type MetricUnit = 'count' | 'pct' | 'minutes' | 'hours' | 'days' | 'cents' | 'ratio' | 'score' | 'months';

export interface MetricDefinition {
  id: string;
  name: string;
  group: MetricGroup;
  description: string;
  /** Numerator / denominator (or aggregate) over named facts, in plain English. */
  formula: string;
  grain: string;
  owner: string;
  /** Illustrative default target; practices override as reference data. */
  target: number | null;
  targetBand?: [number, number];
  targetLabel: string;
  direction: Direction;
  unit: MetricUnit;
  freshness: Freshness;
  /** Source tables the computation reads (owned by other clusters unless core); null values when absent. */
  sources: string[];
  privacyClass: 'T0' | 'T1' | 'T3';
  version: number;
  /** Keywords the Insight Hand matches questions against. */
  keywords: string[];
}

const GROUP_LABEL: Record<MetricGroup, string> = {
  access: 'Access', operations: 'Operations', clinical_quality: 'Clinical quality', patient_experience: 'Patient experience', referrer: 'Referrer',
  revenue_cycle: 'Revenue cycle', finance: 'Finance', workforce: 'Workforce', assets: 'Assets', compliance: 'Compliance and risk', ai_ops: 'AI operations', shareholder: 'Shareholder',
};
export function metricGroupLabel(g: MetricGroup): string {
  return GROUP_LABEL[g];
}

type Partial = Omit<MetricDefinition, 'version' | 'privacyClass' | 'freshness'> & { version?: number; privacyClass?: MetricDefinition['privacyClass']; freshness?: Freshness };
const m = (d: Partial): MetricDefinition => ({ version: 1, privacyClass: 'T1', freshness: 'daily', ...d });

