const byId = new Map(METRICS.map((d) => [d.id, d]));
export function getMetric(id: string): MetricDefinition | undefined {
  return byId.get(id);
}
export function metricsByGroup(): Array<{ group: MetricGroup; label: string; metrics: MetricDefinition[] }> {
  const groups = [...new Set(METRICS.map((d) => d.group))];
  return groups.map((g) => ({ group: g, label: GROUP_LABEL[g], metrics: METRICS.filter((d) => d.group === g) }));
}

/** Is the value on target? Returns 'ok' | 'att' | 'crit' | 'none' for tile toning. */
export function assessAgainstTarget(def: MetricDefinition, value: number | null): 'ok' | 'att' | 'crit' | 'none' {
  if (value === null || value === undefined || Number.isNaN(value)) return 'none';
  if (def.direction === 'band') {
    if (!def.targetBand) return 'none';
    const [lo, hi] = def.targetBand;
    if (value >= lo && value <= hi) return 'ok';
    const span = hi - lo || 1;
    return value < lo - span * 0.5 || value > hi + span * 0.5 ? 'crit' : 'att';
  }
  if (def.target === null) return 'none';
  const t = def.target;
  if (def.direction === 'higher') {
    if (value >= t) return 'ok';
    return value >= t * 0.9 ? 'att' : 'crit';
  }
  if (value <= t) return 'ok';
  return value <= t * 1.25 || value - t <= 1 ? 'att' : 'crit';
}
